{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C45"],
      "claim": "Levomepromazine, a methoxy-substituted tricyclic phenothiazine with a dimethylaminopropyl side chain, has absolute oral bioavailability of 30-70% in humans, supporting F >= 20% for the query's similar methoxy-tricyclic basic-amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Clomipramine, a tricyclic dibenzazepine with a dimethylaminopropyl side chain, has absolute oral bioavailability of 36-68% (mean 48%) versus IV in healthy volunteers, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Imipramine, a closely related tricyclic antidepressant with a dimethylaminopropyl side chain, has an absolute oral bioavailability of about 40% versus IV, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Promethazine, a phenothiazine with a dimethylaminopropyl side chain, has an absolute oral bioavailability of 25% versus IV, which is above the 20% threshold and supports a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Venlafaxine, containing a methoxyphenyl and dimethylaminoethyl motif, has an absolute oral bioavailability of 40-45% versus IV, supporting high bioavailability for the query's methoxyphenyl and dimethylaminoethyl features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Eslicarbazepine acetate, an acetate ester with a tricyclic core, shows >90% oral bioavailability despite first-pass hydrolysis, indicating that the query's acetate ester does not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Prothipendyl, a tricyclic S,N-containing analogue with a dimethylaminopropyl side chain, has low absolute bioavailability in healthy volunteers; this is contradictory evidence but has lower transferability and is outweighed by multiple high-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is diltiazem, whose known absolute oral bioavailability is approximately 40%, well above the 20% threshold. Multiple structurally related tricyclic and basic-amine drugs (levomepromazine, clomipramine, imipramine, promethazine, venlafaxine) show oral bioavailability values of 25-70%, all supporting a high prediction. The single low-F analogue, prothipendyl, is less transferable and does not overturn the consistent high-F evidence.",
  "evidence_gaps": [
    "No direct diltiazem experimental record is present in the supplied evidence set; the prediction relies on analogue transfer and known diltiazem pharmacology.",
    "First-pass metabolism and ester hydrolysis are not directly quantified for the query in the provided records, though the eslicarbazepine acetate analogue suggests an ester does not necessarily cause low F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

